#include <cassert>
#include <iomanip>
#include <iostream>
#include <string>

int main() {
    std::string str("Short string!");
    std::cout << "Before: " << std::quoted(str) << '\n';
    assert(str.size() == 13);

    str.pop_back();
    std::cout << "After:  " << std::quoted(str) << '\n';
    assert(str.size() == 12);

    str.clear();
    //  str.pop_back(); // undefined behavior
}
